/**
 * monet-rn demo app
 *
 * The M2 smoke screen: one call through the Rust TurboModule proves the
 * whole chain — JS → jsi-turbo → monet-rn crate → vendored monet crates →
 * the platform's native stack — built by the app's own aggregate build
 * (react-native-rust-turbo runs cargo over every installed module package).
 *
 * The import is TypeScript generated by the Rust macro at compile time
 * (packages/monet-rn/generated/rust-turbo/); it appears on the first native
 * build.
 *
 * @format
 */

import React, {useEffect, useState} from 'react';
import {
  SafeAreaView,
  ScrollView,
  StatusBar,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {getMonet} from 'monet-rn/generated/rust-turbo/Monet';

function App(): React.JSX.Element {
  const [rows, setRows] = useState<Array<[string, string]>>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      try {
        const monet = getMonet();
        setRows([
          ['Monet.ping()', String(monet.ping())],
          ['Monet.transportStack', String(monet.transportStack)],
        ]);
      } catch (e) {
        setError(String(e));
      }
    })();
  }, []);

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="dark-content" />
      <ScrollView contentContainerStyle={styles.content}>
        <Text style={styles.title}>monet-rn</Text>
        {error !== null && <Text style={styles.error}>error: {error}</Text>}
        {rows.map(([key, value]) => (
          <View key={key} style={styles.row}>
            <Text style={styles.key}>{key}</Text>
            <Text style={styles.value}>{value}</Text>
          </View>
        ))}
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {flex: 1, backgroundColor: 'white'},
  content: {padding: 16},
  title: {fontSize: 22, fontWeight: '700', marginBottom: 16},
  error: {color: 'red', fontFamily: 'Menlo', fontSize: 12, marginBottom: 8},
  row: {marginBottom: 12},
  key: {fontSize: 13, color: '#666', fontFamily: 'Menlo'},
  value: {fontSize: 15, fontFamily: 'Menlo'},
});

export default App;
